    """Return True when the letters of text form a palindrome, ignoring case."""
    raise NotImplementedError

solution:
def is_palindrome(text):
    letters = [char.lower() for char in text if char.isalpha()]
    return letters == letters[::-1]

starter:
def format_table(rows):
    """Return the rows rendered as right-aligned columns separated by one space."""
    raise NotImplementedError

solution:
def format_table(rows):
    if not rows:
        return ""
    widths = [max(len(str(row[index])) for row in rows) for index in range(len(rows[0]))]
    lines = []
    for row in rows:
        lines.append(" ".join(str(value).rjust(width) for value, width in zip(row, widths)))
    return "\n".join(lines)

