def retry_once(func, *args, **kwargs):
    """Call func once and retry exactly once if the first call raises."""
    raise NotImplementedError

tests.code:
_fail_calls = []
def _fails():
    _fail_calls.append(1)
    raise ValueError("nope")
try:
    retry_once(_fails)
except ValueError as exc:
    assert str(exc) == "nope"
else:
    assert False
assert len(_fail_calls) == 2

solution:
def retry_once(func, *args, **kwargs):
    try:
        return func(*args, **kwargs)
    except Exception:
        return func(*args, **kwargs)

