    raise NotImplementedError


def read_lines(path):
    """Return the lines of path with trailing newlines removed."""
    raise NotImplementedError

solution:
def write_lines(path, lines):
    with open(path, "w", encoding="utf-8") as handle:
        for line in lines:
            handle.write(line + "\n")


def read_lines(path):
    with open(path, "r", encoding="utf-8") as handle:
        return [line[:-1] if line.endswith("\n") else line for line in handle]

starter:
def sum_csv_column(path, column):
    """Return the sum of the numeric cells in the named CSV column."""
    raise NotImplementedError

solution:
import csv


def sum_csv_column(path, column):
    total = 0.0
    with open(path, "r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames is None or column not in reader.fieldnames:
            raise KeyError(column)
        for row in reader:
            raw = row.get(column)
            if raw is None or raw.strip() == "":
                continue
            total += float(raw)
    return total
